 /** Message keys per language, for checks. */
 export const messageKeys = (lang) => Object.keys(MESSAGES[lang] ?? {});
+
+/** Picks `ko` or `en` from an Accept-Language header (q-values, region tags); else `fallback`. */
+export function pickLanguage(header, fallback = "en") {
+  if (typeof header !== "string") return fallback;
+  let best = null;
+  let bestQ = 0;
+  for (const part of header.split(",")) {
+    const [tag, ...attrs] = part.trim().split(";");
+    const base = tag.trim().toLowerCase().split("-")[0];
+    if (base !== "ko" && base !== "en") continue;
+    let q = 1;
+    for (const a of attrs) {
+      const m = /^\s*q\s*=\s*([0-9.]+)\s*$/i.exec(a);
+      if (m) q = Number(m[1]);
+    }
+    if (Number.isFinite(q) && q > bestQ) {
+      best = base;
+      bestQ = q;
+    }
+  }
+  return best ?? fallback;
+}
